-- Passage wg3-narrative-writing-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('23ddbd72-bc76-58e8-b44e-a11008caf5a5', 'wg3-narrative-writing-p07', (select id from public.skills where slug = 'write-g3-narrative-writing'), null,
        '3-5', $q$The Tide Pool$q$, $q$(1) Last summer, my family drove to a beach to explore tide pools. (2) Mom told us to step only on dry rocks so we would not slip. (3) I knelt beside a pool of clear, cold water. (4) At first, it looked empty. (5) Then a tiny crab scuttled sideways out from under a rock. (6) I gasped and pointed.

(7) My brother Tariq leaned so close that his nose almost touched the water. (8) Beside the crab, a purple sea star clung to the rock. (9) ________ (10) We watched for a long time without saying a word. (11) Finally, the tide came back in, and we had to leave.$q$, 'draft')
