  ('259562fe-547c-5f6c-8757-3738cdaf7393', null, (select id from public.skills where slug = 'write-g3-narrative-writing'), null, 'hard',
   $q$Why does the writer include sentence 4, "At first, it looked empty"?$q$, $q$[{"text":"It sets up a surprise, so finding the crab feels more exciting.","is_correct":true},{"text":"It shows that the trip to the beach was boring.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It tells the reader how the story will end.","is_correct":false,"misconception_token":"confuses-event-with-ending"},{"text":"It describes what Tariq is doing at the pool.","is_correct":false,"misconception_token":"wrong-character"}]$q$::jsonb, $q$It sets up a surprise, so finding the crab feels more exciting.$q$, $q$Because the pool seems empty, the crab in sentence 5 and the gasp in sentence 6 feel like a surprise. The trip was not boring, since the writer gasps and watches for a long time.$q$, 'draft', '23ddbd72-bc76-58e8-b44e-a11008caf5a5')
